-- ---------------------------------------------------------------------------
-- Revert the multi-language courses: drop the Spanish/Portuguese planet sets
-- and their content, then remove the language plumbing columns.
-- ---------------------------------------------------------------------------

-- Content of the Spanish (e-prefixed) and Portuguese (f-prefixed) courses.
DELETE FROM lesson_steps
WHERE planet_id IN (
    'e1111111-1111-4111-8111-111111111111', 'e2222222-2222-4222-8222-222222222222',
    'e3333333-3333-4333-8333-333333333333', 'e4444444-4444-4444-8444-444444444444',
    'e5555555-5555-4555-8555-555555555555', 'e6666666-6666-4666-8666-666666666666',
    'e7777777-7777-4777-8777-777777777777', 'e8888888-8888-4888-8888-888888888888',
    'f1111111-1111-4111-8111-111111111111', 'f2222222-2222-4222-8222-222222222222',
    'f3333333-3333-4333-8333-333333333333', 'f4444444-4444-4444-8444-444444444444',
    'f5555555-5555-4555-8555-555555555555', 'f6666666-6666-4666-8666-666666666666',
    'f7777777-7777-4777-8777-777777777777', 'f8888888-8888-4888-8888-888888888888'
);

DELETE FROM planet_lessons
WHERE planet_id IN (
    'e1111111-1111-4111-8111-111111111111', 'e2222222-2222-4222-8222-222222222222',
    'e3333333-3333-4333-8333-333333333333', 'e4444444-4444-4444-8444-444444444444',
    'e5555555-5555-4555-8555-555555555555', 'e6666666-6666-4666-8666-666666666666',
    'e7777777-7777-4777-8777-777777777777', 'e8888888-8888-4888-8888-888888888888',
    'f1111111-1111-4111-8111-111111111111', 'f2222222-2222-4222-8222-222222222222',
    'f3333333-3333-4333-8333-333333333333', 'f4444444-4444-4444-8444-444444444444',
    'f5555555-5555-4555-8555-555555555555', 'f6666666-6666-4666-8666-666666666666',
    'f7777777-7777-4777-8777-777777777777', 'f8888888-8888-4888-8888-888888888888'
);

DELETE FROM planet_sentences
WHERE planet_id IN (
    'e1111111-1111-4111-8111-111111111111', 'e2222222-2222-4222-8222-222222222222',
    'e3333333-3333-4333-8333-333333333333', 'e4444444-4444-4444-8444-444444444444',
    'e5555555-5555-4555-8555-555555555555', 'e6666666-6666-4666-8666-666666666666',
    'e7777777-7777-4777-8777-777777777777', 'e8888888-8888-4888-8888-888888888888',
    'f1111111-1111-4111-8111-111111111111', 'f2222222-2222-4222-8222-222222222222',
    'f3333333-3333-4333-8333-333333333333', 'f4444444-4444-4444-8444-444444444444',
    'f5555555-5555-4555-8555-555555555555', 'f6666666-6666-4666-8666-666666666666',
    'f7777777-7777-4777-8777-777777777777', 'f8888888-8888-4888-8888-888888888888'
);

DELETE FROM planets
WHERE language IN ('es', 'pt');

-- Back to a single, globally-numbered planet set.
ALTER TABLE planets DROP CONSTRAINT planets_language_number_key;
ALTER TABLE planets ADD CONSTRAINT planets_number_key UNIQUE (number);

ALTER TABLE planets DROP COLUMN language;
ALTER TABLE users DROP COLUMN language;
ALTER TABLE planet_sentences DROP COLUMN es;
